function receiptConfig(settings, raw, now) {
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (
    !uuid.test(settings.modelId) ||
    !/^app[A-Za-z0-9]{14}$/.test(settings.baseId) ||
    !/^tbl[A-Za-z0-9]{14}$/.test(settings.tableId)
  ) {
    return {
      next: false,
      status: 503,
      body: { error: "Configure the Mindee model and Airtable destination." },
    };
  }
  if (!raw?.length)
    return {
      next: false,
      status: 400,
      body: { error: "Send a receipt file as the raw request body." },
    };
  if (raw.length > 10 * 1024 * 1024)
    return {
      next: false,
      status: 413,
      body: { error: "The receipt exceeds the 10 MiB upload limit." },
    };
  const hex = raw.subarray(0, 12).toString("hex");
  const magic = raw.subarray(0, 12).toString("ascii");
  let filetype;
  if (hex.startsWith("255044462d")) filetype = ["application/pdf", "pdf"];
  else if (hex.startsWith("ffd8ff")) filetype = ["image/jpeg", "jpg"];
  else if (hex.startsWith("89504e470d0a1a0a")) filetype = ["image/png", "png"];
  else if (magic.startsWith("RIFF") && magic.slice(8, 12) === "WEBP")
    filetype = ["image/webp", "webp"];
  else if (hex.startsWith("49492a00") || hex.startsWith("4d4d002a"))
    filetype = ["image/tiff", "tiff"];
  else if (magic.slice(4, 8) === "ftyp" && /^(heic|heix|hevc|hevx)$/.test(magic.slice(8, 12)))
    filetype = ["image/heic", "heic"];
  else if (magic.slice(4, 8) === "ftyp" && /^(mif1|msf1)$/.test(magic.slice(8, 12)))
    filetype = ["image/heif", "heif"];
  if (!filetype)
    return { next: false, status: 415, body: { error: "Send a supported PDF or receipt image." } };
  return {
    next: true,
    ...settings,
    deadline: now + 55000,
    mimeType: filetype[0],
    fileName: "receipt." + filetype[1],
  };
}
const settings = {
  modelId: "YOUR_MINDEE_MODEL_ID",
  baseId: "YOUR_AIRTABLE_BASE_ID",
  tableId: "YOUR_AIRTABLE_TABLE_ID",
  fieldNames: {
    category: "purchase_category",
    date: "date",
    currency: "currency",
    locale: "locale",
    merchant: "supplier_name",
    time: "time",
    total: "total_amount",
  },
};
let raw;
try {
  raw = await helpers.getBinaryDataBuffer(0, "data");
} catch {}
const config = receiptConfig(settings, raw, Date.now());
if (!config.next) return { json: config };
return {
  json: config,
  binary: {
    receipt: { ...$input.item.binary.data, mimeType: config.mimeType, fileName: config.fileName },
  },
};

function mindeeJob(status, data, config) {
  const job = data?.job;
  if (
    status !== 202 ||
    !/^([0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i.test(
      job?.id ?? "",
    ) ||
    job.model_id?.toLowerCase?.() !== config.modelId.toLowerCase()
  ) {
    return { next: false, status: 502, body: { error: "Mindee did not confirm the receipt job." } };
  }
  return { next: true, id: job.id };
}
return {
  json: mindeeJob(
    $json.statusCode,
    $json.body,
    $("Set destinations and check the file").first().json,
  ),
};

function mindeeStatus(status, data, expected, config, attempt, now) {
  const job = data?.job;
  if (
    status !== 200 ||
    job?.id !== expected.id ||
    job?.model_id?.toLowerCase?.() !== config.modelId.toLowerCase()
  ) {
    return {
      again: false,
      next: false,
      status: 502,
      body: { error: "Mindee did not confirm the same receipt job." },
    };
  }
  if (job.status === "Failed")
    return {
      again: false,
      next: false,
      status: 502,
      body: { error: "Mindee could not process this receipt." },
    };
  if (now + 12000 >= config.deadline || (job.status === "Processing" && attempt >= 8)) {
    return {
      again: false,
      next: false,
      status: 504,
      body: {
        error: "Mindee did not finish in the time available. No Airtable write was attempted.",
      },
    };
  }
  if (job.status === "Processing") return { again: true, next: false };
  const resultPattern =
    /^https:\/\/api-v2\.mindee\.net\/v2\/(?:products\/extraction\/results|inferences)\/([0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i;
  const link = typeof job.result_url === "string" ? job.result_url.match(resultPattern) : null;
  if (job.status !== "Processed" || !link)
    return {
      again: false,
      next: false,
      status: 502,
      body: { error: "Mindee did not return a usable inference link." },
    };
  return { again: false, next: true, resultId: link[1], resultUrl: job.result_url };
}
return {
  json: mindeeStatus(
    $json.statusCode,
    $json.body,
    $("Check the Mindee job receipt").first().json,
    $("Set destinations and check the file").first().json,
    $runIndex + 1,
    Date.now(),
  ),
};

function receiptFields(status, data, state, job, config, now) {
  if (now + 7000 >= config.deadline) {
    return {
      next: false,
      status: 504,
      body: {
        error: "The receipt exceeded the processing deadline. No Airtable write was attempted.",
      },
    };
  }
  const inference = data?.inference;
  if (
    status !== 200 ||
    inference?.id !== state.resultId ||
    inference?.job?.id !== job.id ||
    inference?.model?.id?.toLowerCase?.() !== config.modelId.toLowerCase()
  ) {
    return {
      next: false,
      status: 502,
      body: { error: "Mindee did not return the inference for this receipt." },
    };
  }
  const extract = inference.result?.fields;
  const fields = {};
  for (const [target, source] of Object.entries(config.fieldNames)) {
    const parsed = extract?.[source];
    const item = parsed?.value;
    if (
      parsed?.error ||
      (target === "total" ? !Number.isFinite(item) : typeof item !== "string" || !item.trim())
    ) {
      return {
        next: false,
        status: 422,
        body: { error: "A required receipt field was missing or unreadable.", field: target },
      };
    }
    fields[target] = item;
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fields.date) || !/^[A-Z]{3}$/.test(fields.currency)) {
    return {
      next: false,
      status: 422,
      body: { error: "The receipt needs an ISO date and three-letter currency code." },
    };
  }
  return { next: true, fields };
}
return {
  json: receiptFields(
    $json.statusCode,
    $json.body,
    $("Check job status and time remaining").last(0, -1).json,
    $("Check the Mindee job receipt").first().json,
    $("Set destinations and check the file").first().json,
    Date.now(),
  ),
};

function confirmedExpense(status, data, expected) {
  const record = Array.isArray(data?.records) && data.records.length === 1 ? data.records[0] : null;
  if (
    (status !== 200 && status !== 201) ||
    !/^rec[A-Za-z0-9]+$/.test(record?.id ?? "") ||
    data.details ||
    record.details ||
    Object.entries(expected).some(([key, value]) => record.fields?.[key] !== value)
  ) {
    return {
      status: 502,
      body: {
        error: "Airtable did not confirm the receipt. Check the table before submitting again.",
      },
    };
  }
  const fields = Object.fromEntries(Object.keys(expected).map((key) => [key, record.fields[key]]));
  const { currency, total, category, merchant, date, time } = fields;
  return {
    status: 200,
    body: [
      {
        data: fields,
        message: `You spent ${currency} ${total} on ${category} at ${merchant} on ${date} at ${time}`,
      },
    ],
  };
}
return {
  json: confirmedExpense(
    $json.statusCode,
    $json.body,
    $("Validate the seven receipt fields").first().json.fields,
  ),
};
